import{_ as l,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2018-May-10 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-May-10 :: Ceph Performance Weekly","date":"2018-05-10T00:00:00.000Z","updated":"2018-05-11T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","BlueStore","BlueFS","OSDevice (OSD)","PG (Placement Group)","RADOS","Radosgw"],"categories":["存储系统","性能分析","代码审查","会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-May-10_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-May-10_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),i={name:"posts/2018/2018-May-10_-_-_Ceph_Performance_Weekly.md"};function s(p,e,n,a,_,g){return t(),r("div",null,[...e[0]||(e[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Peter、Igor、Chief、Adam、Nick、Josh等</p><p><strong>会议主题</strong>： Ceph分布式存储相关研发讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. 代码审查与Pull Request</strong></p><ul><li>Peter提出一个针对Blue Store的新位图定位器设计，旨在提升对话场景中的性能。该设计通过减少空间占用，提高查找速度，并支持并发请求处理。</li><li>Igor展示了位图定位器的性能比较，显示其在所有测试案例中均优于现有定位器，特别是在随机分配场景下。</li><li>Adam提交了一个代码审查请求，涉及可能影响性能的更改。目前正在进行进一步调查。</li><li>Chief关闭了两个Pull Request，其中一个与Rgw相关，另一个原因不明。</li><li>Nick探讨了PG数量和OSD性能，讨论了如何处理大容量驱动器和高速I/O驱动器对集群性能的影响。</li></ul><p><strong>2. 位图定位器设计</strong></p><ul><li>Igor详细介绍了新位图定位器的设计，包括数据结构、内存占用和性能优势。</li><li>讨论了位图定位器在连续分配场景下的局限性，以及如何通过优化内存表示来减少内存消耗。</li><li>比较了位图定位器与现有B树定位器，并强调了位图定位器在大型存储设备上的优势。</li></ul><p><strong>3. PG数量和OSD性能</strong></p><ul><li>Nick探讨了PG数量和OSD性能，讨论了如何处理大容量驱动器和高速I/O驱动器对集群性能的影响。</li><li>Josh指出，大容量硬盘并不会显著提高I/O性能，因为随机写入速度较慢。</li><li>讨论了使用混合布局来优化硬盘性能的想法，例如在硬盘的前端使用更细粒度的布局。</li></ul><p><strong>4. 其他议题</strong></p><ul><li>讨论了XFS日志对性能的影响，并建议进行更多测试。</li><li>讨论了在RBD级别实现日志接口的想法，以提高并行性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续研究Adam提交的代码审查请求。</li><li>对位图定位器进行更多测试，包括连续分配场景和大型存储设备。</li><li>研究混合布局对硬盘性能的影响。</li><li>进行更多测试，以了解XFS日志对性能的影响。</li><li>考虑在RBD级别实现日志接口。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议重点讨论了Ceph分布式存储的性能优化，包括位图定位器设计、PG数量和OSD性能等问题。会议达成了多项共识，并确定了后续行动计划，以进一步提升Ceph的存储性能。</p>",18)])])}const d=l(i,[["render",s]]);export{u as __pageData,d as default};
